@startuml

class Aircraft {
  + Name : string
  + Type : string
  + YearOfManufacture : int
  + NextInspectionDate : date
}

class PassengerAircraft extends Aircraft {
  + NumberOfSeats : int
}

class SeatCategory {
  + Designation : string
  + OffersEntertainment : boolean
  + NumberOfSeats : int
}

class Flight {
  + FlightNumber : string
  + Date : date
}

class Passenger {
  + Name : string
  + PassportNumber : string
}

class Ticket {
  + TicketNumber : string
  + Price : double
  + UpgradeDesired : boolean
}

class Airline {
  + Name : string
}

class FlightAttendant {
  + Name : string
  + DateOfEmployment : date
  + IsChiefStewardess : boolean
}

class Pilot {
  + Name : string
  + DateOfEmployment : date
  + License : string
}

class Airport {
  + Name : string
  + Address : string
  + NumberOfRunways : int
}

Aircraft "0..*" -- "1" Airline : belongs to
Aircraft "0..*" -- "0..1" Airport : home airport
Flight "0..*" -- "1" Aircraft : performs
Flight "0..*" -- "1" Airport : departure airport
Flight "0..*" -- "1" Airport : destination airport
Passenger "1..*" -- "1..*" Flight : takes part in
Ticket "0..*" -- "1" Flight : for
Ticket "0..*" -- "1" Passenger : for
Ticket "0..*" -- "1" SeatCategory : for
PassengerAircraft "1" *-- "1..*" SeatCategory : has
Flight "1" -- "1" Pilot : captain
Flight "1" -- "1..2" Pilot : co-pilot
Flight "1" -- "1..*" FlightAttendant : works on

@enduml

